_CORE_SRC = '# Action format: "list[tuple[int, int, int]]", as [(from_node, to_node, count), ...].\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# "profit_p = revenue_p - upkeep_p"\n# Ownership persists without troops; capture requires two consecutive strict majorities.\n# Unlike capacity-sharing games, capture rewards are not concave. The allocator therefore\n# evaluates complete majority-sized bundles, rather than assigning fictitious marginal\n# rewards to units that cannot complete a capture.\n\nimport heapq\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """The specification\'s exact per-turn profit."""\n    return float(sum(v for v, owner in zip(values, owned) if owner)\n                 - UPKEEP * (UNITS_PER_PLAYER - units_at_base))\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    for u, v, length in edges:\n        adjacency[u].append((v, length))\n        adjacency[v].append((u, length))\n        lengths[u, v] = length\n        lengths[v, u] = length\n    for row in adjacency:\n        row.sort()\n\n    distances = []\n    hops = []\n    for start in range(n):\n        dist = [10**6] * n\n        first = [n] * n\n        dist[start] = 0\n        first[start] = start\n        queue = [(0, start, start)]\n        while queue:\n            cost, hop, u = heapq.heappop(queue)\n            if cost != dist[u] or hop != first[u]:\n                continue\n            for v, length in adjacency[u]:\n                new_cost = cost + length\n                new_hop = v if u == start else hop\n                if (new_cost, new_hop) < (dist[v], first[v]):\n                    dist[v], first[v] = new_cost, new_hop\n                    heapq.heappush(queue, (new_cost, new_hop, v))\n        distances.append(dist)\n        hops.append(first)\n    return adjacency, lengths, distances, hops\n\n\ndef ownership_stream(owner, own_lead, enemy_lead, own_arrivals, enemy_counts,\n                     horizon):\n    """Exact ownership checks against the stationary-visible-opponent forecast."""\n    arrivals = [0] * horizon\n    for arrival in own_arrivals:\n        if arrival < horizon:\n            arrivals[max(0, arrival)] += 1\n    count = 0\n    result = []\n    first_capture = None\n    for step in range(horizon):\n        count += arrivals[step]\n        enemy = enemy_counts[step]\n        if count > enemy:\n            own_lead += 1\n            enemy_lead = 0\n            if own_lead >= 2:\n                if owner != 1 and first_capture is None:\n                    first_capture = step\n                owner = 1\n        elif enemy > count:\n            enemy_lead += 1\n            own_lead = 0\n            if enemy_lead >= 2:\n                owner = -1\n        else:\n            own_lead = enemy_lead = 0\n        result.append(owner)\n    return result, first_capture\n\n\ndef legal_action(assignments, tokens, units, base, hops, lengths):\n    """Replay against start-of-turn availability; arrivals cannot move this turn."""\n    combined = {}\n    for token_id, target in enumerate(assignments):\n        position, delay, movable = tokens[token_id]\n        if not movable or position == target:\n            continue\n        destination = hops[position][target]\n        if (position, destination) not in lengths:\n            continue\n        pair = (position, destination)\n        combined[pair] = combined.get(pair, 0) + 1\n\n    remaining = list(units)\n    action = []\n    for (source, destination), count in sorted(combined.items()):\n        if not (0 <= source < len(remaining) and\n                0 <= destination < len(remaining)):\n            continue\n        if source == destination or (source, destination) not in lengths:\n            continue\n        count = min(count, remaining[source])\n        if count > 0:\n            action.append((int(source), int(destination), int(count)))\n            remaining[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.previous_targets = {}\n        self.bad_reports = 0\n        self.conservative = False\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n        adjacency, lengths, distances, hops = self.map_data\n\n        if (obs.get("n_invalid_actions_last_turn", 0) or\n                not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n\n        base = int(obs["player_base"])\n        enemy_base = int(obs["opponent_base"])\n        turn = int(obs.get("turn", 0))\n        horizon = max(0, N_TURNS - turn)\n        units = obs["player_units"]\n        if horizon == 0:\n            return []\n\n        # A transit is an immutable delayed source at the end of its current edge.\n        tokens = []\n        for position, count in enumerate(units):\n            for _ in range(count):\n                tokens.append((position, 0, True))\n        for source, destination, count, arrival in obs.get("player_transits", []):\n            for _ in range(count):\n                tokens.append((destination, max(0, arrival - turn), False))\n\n        targets = [base] * len(tokens)\n        if not tokens:\n            return []\n        if self.conservative:\n            return legal_action(targets, tokens, units, base, hops, lengths)\n\n        values = obs["node_value"]\n        owned = obs["player_owned"]\n        enemy_owned = obs["opponent_owned"]\n        own_leads = obs["player_lead_turns"]\n        enemy_leads = obs["opponent_lead_turns"]\n        enemies = obs["opponent_units"]\n\n        # Opponent units stay where visible. Their already committed transits land\n        # on schedule, and remain at their destinations.\n        enemy_forecast = [[enemies[v]] * horizon for v in range(n)]\n        for source, destination, count, arrival in obs.get("opponent_transits", []):\n            first_end = max(0, arrival - turn - 1)\n            for step in range(first_end, horizon):\n                enemy_forecast[destination][step] += count\n\n        baseline_cost = []\n        for position, delay, movable in tokens:\n            return_time = delay + distances[position][base]\n            baseline_cost.append(\n                UPKEEP * min(horizon, max(0, return_time - 1))\n            )\n\n        candidates = []\n        baseline_streams = {}\n        for node in range(n):\n            if node in (base, enemy_base) or values[node] <= 0:\n                continue\n            maximum_enemy = max(enemy_forecast[node], default=0)\n            if owned[node] and maximum_enemy == 0:\n                continue\n            owner = 1 if owned[node] else (-1 if enemy_owned[node] else 0)\n            baseline, _ = ownership_stream(\n                owner, 0, enemy_leads[node], [],\n                enemy_forecast[node], horizon\n            )\n            baseline_streams[node] = baseline\n            candidates.append(node)\n\n        available = list(range(len(tokens)))\n        unfinished = list(candidates)\n        selected_counts = {}\n\n        # Greedy bundle allocation. Every completed iteration leaves a fully valid\n        # return-home fallback for all units not assigned to a worthwhile mission.\n        while available and unfinished and time.perf_counter() < deadline:\n            best = None\n            best_score = 0.0\n            for node in unfinished:\n                if time.perf_counter() >= deadline:\n                    break\n                enemy_max = max(enemy_forecast[node], default=0)\n                required = enemy_max if owned[node] else enemy_max + 1\n                required = max(1, required)\n                sizes = sorted({required, enemy_max + 1})\n                ranked = sorted(\n                    available,\n                    key=lambda i: (\n                        tokens[i][1] + distances[tokens[i][0]][node],\n                        -baseline_cost[i],\n                        i\n                    )\n                )\n                for size in sizes:\n                    if size > len(ranked):\n                        continue\n                    chosen = ranked[:size]\n                    arrivals = []\n                    for i in chosen:\n                        position, delay, movable = tokens[i]\n                        travel = delay + distances[position][node]\n                        arrivals.append(max(0, travel - 1))\n                    owner = 1 if owned[node] else (-1 if enemy_owned[node] else 0)\n                    stream, capture = ownership_stream(\n                        owner, own_leads[node], enemy_leads[node],\n                        arrivals, enemy_forecast[node], horizon\n                    )\n                    reward = values[node] * sum(\n                        after - before\n                        for after, before in zip(stream, baseline_streams[node])\n                    )\n                    if enemy_max:\n                        # Holding a contested node incurs upkeep through the horizon.\n                        cost = sum(UPKEEP * horizon - baseline_cost[i]\n                                   for i in chosen)\n                    else:\n                        if capture is None:\n                            continue\n                        # Capture, then return: the final landing at home is free.\n                        away_turns = min(\n                            horizon, capture + distances[node][base]\n                        )\n                        cost = sum(UPKEEP * away_turns - baseline_cost[i]\n                                   for i in chosen)\n                    net = reward - cost\n                    if net <= 0:\n                        continue\n                    # Small hysteresis: never turn a losing mission into a winning\n                    # one, but prefer continuing an otherwise similar target.\n                    sticky = min(4.0, 0.025 * net) if (\n                        self.previous_targets.get(node, 0) >= size\n                    ) else 0.0\n                    score = (net + sticky) / (size ** 0.25)\n                    if score > best_score:\n                        best_score = score\n                        best = (node, chosen)\n            if best is None:\n                break\n            node, chosen = best\n            chosen_set = set(chosen)\n            for i in chosen:\n                targets[i] = node\n            selected_counts[node] = len(chosen)\n            available = [i for i in available if i not in chosen_set]\n            unfinished.remove(node)\n\n        self.previous_targets = selected_counts\n        return legal_action(targets, tokens, units, base, hops, lengths)\n'
_CORE_CLASS = 'Strategy'
